CREATE TABLE IF NOT EXISTS `suppliers` (`id` integer PRIMARY KEY AUTOINCREMENT NOT NULL, `name` text NOT NULL UNIQUE, `payment_terms_days` integer DEFAULT 7 NOT NULL, `contact` text, `active` integer DEFAULT true NOT NULL);
CREATE TABLE IF NOT EXISTS `supplier_invoices` (`id` integer PRIMARY KEY AUTOINCREMENT NOT NULL, `supplier_id` integer NOT NULL, `invoice_number` text NOT NULL UNIQUE, `delivery_date` text NOT NULL, `due_date` text NOT NULL, `amount` real NOT NULL, `balance` real NOT NULL, `status` text DEFAULT 'OPEN' NOT NULL, `created_at` text NOT NULL, FOREIGN KEY (`supplier_id`) REFERENCES `suppliers`(`id`));
CREATE INDEX IF NOT EXISTS `supplier_invoice_due_idx` ON `supplier_invoices` (`due_date`,`status`);
CREATE TABLE IF NOT EXISTS `financial_transactions` (`id` integer PRIMARY KEY AUTOINCREMENT NOT NULL, `reference` text NOT NULL UNIQUE, `transaction_type` text NOT NULL, `account_name` text NOT NULL, `amount` real NOT NULL, `reason` text NOT NULL, `payment_method` text, `created_at` text NOT NULL);
